/**
 * 退货工作台 / 售后处理事项的部署引导数据（菜单、角色授权、页面模型、外部数据源集合）。
 *
 * 生产 NocoBase 无法通过 SSH 上传 SQL、也没有管理员 token 触发数据源刷新，
 * 因此把一次性 PG 数据放在插件启动时幂等写入；只在检测不到退货工作台菜单时执行。
 * 执行后再次重启即可让外部数据源集合进入缓存。
 */
import type { Application } from '@nocobase/server';

const STATEMENTS: string[] = JSON.parse(Buffer.from('', 'base64').toString('utf8'));

export async function applyReturnBootstrap(app: Application) {
  try {
    const [rows] = await app.db.sequelize.query("SELECT 1 FROM \"desktopRoutes\" WHERE id = '1794865399332487' LIMIT 1");
    if (Array.isArray(rows) && rows.length > 0) {
      return;
    }
    let applied = 0;
    for (const statement of STATEMENTS) {
      try {
        await app.db.sequelize.query(statement);
        applied += 1;
      } catch (error: any) {
        app.logger?.warn?.(`[return-bootstrap] skip: ${error?.message || error}`);
      }
    }
    app.logger?.info?.(`[return-bootstrap] applied ${applied}/${STATEMENTS.length} statements`);
  } catch (error: any) {
    app.logger?.warn?.(`[return-bootstrap] failed: ${error?.message || error}`);
  }
}
